import pyomo.environ as pyo

DATA = {
    "products": ["crepe", "sponge", "birthday"],
    "resources": ["batter", "milk"],
    "profit": {"crepe": 12, "sponge": 10, "birthday": 15},
    "usage": {
        "batter": {"crepe": 400, "sponge": 500, "birthday": 450},
        "milk": {"crepe": 200, "sponge": 300, "birthday": 350},
    },
    "availability": {"batter": 20000, "milk": 14000},
}


def build_model(data=None):
    d = data or DATA

    model = pyo.ConcreteModel()

    model.P = pyo.Set(initialize=d["products"])
    model.R = pyo.Set(initialize=d["resources"])

    model.x = pyo.Var(model.P, within=pyo.NonNegativeIntegers)

    def obj_rule(m):
        return sum(d["profit"][p] * m.x[p] for p in m.P)

    model.obj = pyo.Objective(rule=obj_rule, sense=pyo.maximize)

    def resource_rule(m, r):
        return sum(d["usage"][r][p] * m.x[p] for p in m.P) <= d["availability"][r]

    model.resource_limit = pyo.Constraint(model.R, rule=resource_rule)

    return model

import pyomo.environ as pyo

DATA = {
    "cakes": ["crepe", "sponge", "birthday"],
    "resources": ["batter", "milk"],
    "profit": {"crepe": 12, "sponge": 10, "birthday": 15},
    "usage": {
        "batter": {"crepe": 400, "sponge": 500, "birthday": 450},
        "milk": {"crepe": 200, "sponge": 300, "birthday": 350},
    },
    "available": {"batter": 20000, "milk": 14000},
}


def build_model(data=None):
    d = data or DATA
    model = pyo.ConcreteModel()

    model.CAKES = pyo.Set(initialize=d["cakes"])
    model.RESOURCES = pyo.Set(initialize=d["resources"])

    model.make = pyo.Var(
        model.CAKES,
        within=pyo.NonNegativeIntegers,
        bounds=(0, None),
    )

    def profit_rule(m):
        return sum(d["profit"][c] * m.make[c] for c in m.CAKES)

    model.obj = pyo.Objective(expr=profit_rule, sense=pyo.maximize)

    def resource_rule(m, r):
        return sum(d["usage"][r][c] * m.make[c] for c in m.CAKES) <= d["available"][r]

    model.resource_limit = pyo.Constraint(model.RESOURCES, rule=resource_rule)

    return model
